711	  }
712	}
713	
714	/**
715	 * Creates a string key for request deduplication purposes.
716	 * This key is used to identify in-flight requests that can be shared.
717	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheKey} cacheKey
718	 * @param {Set<string>} [excludeHeaders] Set of lowercase header names to exclude from the key
