    server.close()
    await client.close()
  })

  await once(server, 'listening')

  const request = { origin, method: 'GET', path: '/' }
  const cacheKey = makeCacheKey({ ...request, headers: {} })

  // Entries like this can be left over from before set-cookie was disallowed
  const writable = store.createWriteStream(cacheKey, {
    statusCode: 200,
    statusMessage: 'OK',
    headers: { 'cache-control': 'public, s-maxage=10', 'set-cookie': 'session=secret' },
    cacheControlDirectives: { public: true, 's-maxage': 10 },
    cachedAt: Date.now(),
    staleAt: Date.now() + 10000,
    deleteAt: Date.now() + 20000
  })
  writable.end('from cache')

  const res = await client.request(request)
  equal(requestsToOrigin, 1)
  equal(res.headers['set-cookie'], undefined)
  strictEqual(await res.body.text(), 'from origin')

  // ... and the offending entry is dropped
  equal(store.get(cacheKey), undefined)
})

